function parseList(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.copy4000.com').replace(/\/$/, '');
  var listHtml = (typeof html === 'string') ? html : '';
  var covers = {}, titles = {}, order = [];
  var re = /<a\s[^>]*href="\/comic\/([a-z0-9_-]+)"[^>]*>([\s\S]{0,800}?)<\/a>/gi;
  var m;
  while ((m = re.exec(listHtml)) !== null) {
    var slug = m[1], block = m[2];
    if (order.indexOf(slug) < 0) order.push(slug);
    if (!covers[slug]) {
      var im = block.match(/<img[^>]*(?:data-src|data-original|src)="([^"]+)"/i);
      if (im) covers[slug] = im[1];
    }
    if (!titles[slug]) {
      var tm = block.match(/<(?:h3|h2|p)[^>]*>([\s\S]*?)<\/(?:h3|h2|p)>/i);
      var t = tm ? tm[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim()
                 : block.replace(/<img[^>]*>/ig, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      if (t && t.indexOf('http') < 0 && t.length <= 40) titles[slug] = t;
    }
  }
  var results = [];
  for (var i = 0; i < order.length; i++) {
    var slug = order[i];
    var title = titles[slug];
    if (!title) continue;
    var cover = covers[slug] || '';
    if (cover && cover.charAt(0) === '/') cover = baseUrl + cover;
    var href = 'comic/' + slug;
    results.push({ id: href, title: title, cover: cover, detailUrl: baseUrl + '/' + href });
  }
  return results;
}

